{
  "description": "Adds /card to save question and answer pairs as lines in cards.md while you study",
  "modules": [
    "./register.js"
  ]
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'card', description: 'Save a flashcard line to cards.md', argumentHint: '[question | answer]', immediate: true })
    return next(e)
  })
  on('command.run', { command: 'card' }, async ($, e) => {
    if (!e.args) return { text: 'Usage: /card question | answer' }
    let existing = ''
    if (await $.fs.exists('cards.md')) existing = await $.fs.read('cards.md')
    await $.fs.write('cards.md', existing + '- ' + '' + e.args + '\n')
    return { text: 'Card saved to cards.md' }
  })
}

