// Stores { last: 'YYYY-MM-DD', days: n } in streak.json.
export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'streak', description: 'Show your study streak', immediate: true })
    return next(e)
  })
  on('command.run', { command: 'streak' }, async ($) => {
    let data = { last: '', days: 0 }
    if (await $.fs.exists('streak.json')) {
      try { data = JSON.parse(await $.fs.read('streak.json')) } catch (err) { /* start fresh */ }
    }
    const today = new Date()
    const todayText = today.toISOString().slice(0, 10)
    const yesterday = new Date(today.getTime() - 86400000).toISOString().slice(0, 10)
    if (data.last !== todayText) {
      data.days = data.last === yesterday ? data.days + 1 : 1
      data.last = todayText
      await $.fs.write('streak.json', JSON.stringify(data))
    }
    return { text: 'Study streak: ' + data.days + ' day(s)' }
  })
}

