{
  "description": "Shows a toast once Claude passes a set number of tool calls; change the limit with /budget",
  "modules": [
    "./register.js"
  ]
}

let limit = 25
let calls = 0
let warned = false

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'budget', description: 'Set the tool call warning limit', argumentHint: '[number]', immediate: true })
    return next(e)
  })
  on('tool.call', async ($, e, next) => {
    calls += 1
    if (calls >= limit && !warned) {
      warned = true
      $.ui.toast('Claude has made ' + calls + ' tool calls. Check this is still on track.')
    }
    return next(e)
  })
  on('command.run', { command: 'budget' }, async ($, e) => {
    if (Number(e.args) > 0) { limit = Number(e.args); warned = false }
    return { text: 'Warning limit is ' + limit + ' tool calls' }
  })
}

